static int p2d89_emit_symbols_basic(P2D89_ShapeId id,const P2D89_Provider *p){static const p2d89_q14 plus[]={-4096,-16384,4096,-16384,4096,-4096,16384,-4096,16384,4096,4096,4096,4096,16384,-4096,16384,-4096,4096,-16384,4096,-16384,-4096,-4096,-4096};if(id==P2D89_SHAPE_PLUS||id==P2D89_SHAPE_CROSS)return p2d89_i_poly(plus,12U,1,p);if(id==P2D89_SHAPE_X){if(!p2d89_i_move(p,-12288,-12288))return 0;if(!p2d89_i_line(p,12288,12288))return 0;if(!p2d89_i_move(p,12288,-12288))return 0;return p2d89_i_line(p,-12288,12288);}if(id==P2D89_SHAPE_MINUS){if(!p2d89_i_move(p,-14336,0))return 0;return p2d89_i_line(p,14336,0);}if(id==P2D89_SHAPE_EXCLAMATION){if(!p2d89_i_move(p,0,-14336))return 0;if(!p2d89_i_line(p,0,6144))return 0;return p2d89_i_point(p,0,12288);}if(id==P2D89_SHAPE_INFINITY){if(!p2d89_i_move(p,0,0))return 0;if(!p2d89_i_cubic(p,-4096,-8192,-14336,-8192,-14336,0))return 0;if(!p2d89_i_cubic(p,-14336,8192,-4096,8192,0,0))return 0;if(!p2d89_i_cubic(p,4096,-8192,14336,-8192,14336,0))return 0;return p2d89_i_cubic(p,14336,8192,4096,8192,0,0);}if(id==P2D89_SHAPE_CHECK){if(!p2d89_i_move(p,-12288,0))return 0;if(!p2d89_i_line(p,-4096,8192))return 0;return p2d89_i_line(p,14336,-12288);}if(id==P2D89_SHAPE_SLASH){if(!p2d89_i_move(p,-8192,14336))return 0;return p2d89_i_line(p,8192,-14336);}if(id==P2D89_SHAPE_BACKSLASH){if(!p2d89_i_move(p,-8192,-14336))return 0;return p2d89_i_line(p,8192,14336);}if(id==P2D89_SHAPE_HASH){if(!p2d89_i_move(p,-6144,-14336))return 0;if(!p2d89_i_line(p,-8192,14336))return 0;if(!p2d89_i_move(p,8192,-14336))return 0;if(!p2d89_i_line(p,6144,14336))return 0;if(!p2d89_i_move(p,-14336,-5120))return 0;if(!p2d89_i_line(p,14336,-5120))return 0;if(!p2d89_i_move(p,-14336,5120))return 0;return p2d89_i_line(p,14336,5120);}if(id==P2D89_SHAPE_HAMBURGER){if(!p2d89_i_move(p,-14336,-8192))return 0;if(!p2d89_i_line(p,14336,-8192))return 0;if(!p2d89_i_move(p,-14336,0))return 0;if(!p2d89_i_line(p,14336,0))return 0;if(!p2d89_i_move(p,-14336,8192))return 0;return p2d89_i_line(p,14336,8192);}if(id==P2D89_SHAPE_ELLIPSIS){if(!p2d89_i_point(p,-8192,0))return 0;if(!p2d89_i_point(p,0,0))return 0;return p2d89_i_point(p,8192,0);}if(id==P2D89_SHAPE_COLON){if(!p2d89_i_point(p,0,-6144))return 0;return p2d89_i_point(p,0,6144);}if(id==P2D89_SHAPE_BULLET)return p2d89_emit_ellipse(4096,4096,1,p);if(id==P2D89_SHAPE_TARGET){if(!p2d89_emit_ellipse(16384,16384,1,p))return 0;if(!p2d89_emit_ellipse(10240,10240,0,p))return 0;if(!p2d89_emit_ellipse(4096,4096,1,p))return 0;return 1;}if(id==P2D89_SHAPE_CROSSHAIR){if(!p2d89_i_move(p,-16384,0))return 0;if(!p2d89_i_line(p,16384,0))return 0;if(!p2d89_i_move(p,0,-16384))return 0;if(!p2d89_i_line(p,0,16384))return 0;return p2d89_emit_ellipse(8192,8192,1,p);}return 0;}
const P2D89_Submodule p2d89_submodule_symbols_basic = { { P2D89_MODULE_SYMBOLS, "symbols", "basic", (unsigned int)(sizeof(shapes)/sizeof(shapes[0])) }, shapes, p2d89_emit_symbols_basic };
